public class PayrollAccount{private double basicSalary,bonus;public PayrollAccount(double s){if(s<0)s=0;basicSalary=s;}public void creditBonus(double a){if(a>0)bonus+=a;}public void deductTax(double p){if(p>=0&&p<=100)basicSalary-=basicSalary*p/100;}public double getNetSalary(){return basicSalary+bonus;}public static void main(String[] z){PayrollAccount p=new PayrollAccount(50000);p.creditBonus(5000);p.deductTax(10);System.out.println("Net salary: Rs "+p.getNetSalary());}}